class _Reminders extends StatefulWidget{const _Reminders();@override State<_Reminders> createState()=>_RemindersState();}
class _RemindersState extends State<_Reminders>{
 final title=TextEditingController();List<Map<String,dynamic>> items=[];bool loading=true;
 @override void initState(){super.initState();load();}
 @override void dispose(){title.dispose();super.dispose();}
 Future<void> load()async{final p=await SharedPreferences.getInstance();try{items=(jsonDecode(p.getString('local_reminders_v1')??'[]') as List).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();}catch(_){items=[];}if(mounted)setState(()=>loading=false);}
 Future<void> save()async{final p=await SharedPreferences.getInstance();await p.setString('local_reminders_v1',jsonEncode(items));}
