 const _ToolCard(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('تذكيراتك الشخصية',style:TextStyle(color:_toolText,fontSize:17,fontWeight:FontWeight.bold)),SizedBox(height:6),Text('تُحفظ محلياً ولا يُنشئ التطبيق تذكيرات تلقائية. تنبيه: هذه قائمة داخل التطبيق حالياً وليست إشعارات نظام تعمل بعد إغلاق التطبيق.',style:TextStyle(color:_toolMuted,height:1.7,fontSize:12))])),
 const SizedBox(height:10),_ToolCard(Column(children:[TextField(controller:title,style:const TextStyle(color:_toolText),decoration:const InputDecoration(labelText:'عنوان التذكير')),const SizedBox(height:8),SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:add,icon:const Icon(Icons.add_alarm),label:const Text('إضافة تذكير')))])),
 const SizedBox(height:10),Text('التذكيرات المحفوظة: '+items.length.toString(),style:const TextStyle(color:_toolText,fontWeight:FontWeight.bold)),
 if(items.isEmpty)const _ToolCard(Text('لا توجد تذكيرات بعد.',style:TextStyle(color:_toolMuted))),
 ...List.generate(items.length,(i){final x=items[i],at=DateTime.parse(x['at'] as String),done=x['done'] as bool? ?? false;return Padding(padding:const EdgeInsets.only(top:8),child:_ToolCard(Row(children:[Checkbox(value:done,onChanged:(_){setState(()=>x['done']=!done);save();}),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(x['title'] as String,style:const TextStyle(color:_toolText)),Text(at.toLocal().toString().substring(0,16),style:const TextStyle(color:_toolMuted,fontSize:11)),if(!done&&at.isBefore(DateTime.now()))const Text('موعد التذكير قد حان',style:TextStyle(color:Colors.orangeAccent,fontSize:10))])),IconButton(onPressed:(){setState(()=>items.removeAt(i));save();},icon:const Icon(Icons.delete_outline,color:_toolMuted))])));}),
 ]);}
class _QuranPlan extends StatefulWidget{const _QuranPlan();@override State<_QuranPlan> createState()=>_QuranPlanState();}
class _QuranPlanState extends State<_QuranPlan>{
 int goal=20,read=0,last=1;List<int> marks=[];String get today=>DateTime.now().toIso8601String().substring(0,10);
 @override void initState(){super.initState();load();}
 Future<void> load()async{final p=await SharedPreferences.getInstance();final date=p.getString('quran_daily_date'),raw=p.getStringList('quran_bookmarks_v1')??[];if(!mounted)return;setState((){goal=(p.getInt('quran_daily_goal')??20).clamp(1,100);read=date==today?(p.getInt('quran_daily_pages')??0):0;last=(p.getInt('quran_last_page')??1).clamp(1,604);marks=raw.map(int.tryParse).whereType<int>().where((v)=>v>0&&v<=604).toSet().toList()..sort();});if(date!=today){await p.setString('quran_daily_date',today);await p.setInt('quran_daily_pages',0);}}
 Future<void> save()async{final p=await SharedPreferences.getInstance();await p.setInt('quran_daily_goal',goal);await p.setInt('quran_daily_pages',read);await p.setString('quran_daily_date',today);await p.setStringList('quran_bookmarks_v1',marks.map((v)=>v.toString()).toList());}
 Future<void> bookmark()async{setState((){if(!marks.contains(last))marks.add(last);marks.sort();});await save();}
 @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(14),children:[
 _ToolCard(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('الورد اليومي وخطة الختمة',style:TextStyle(color:_toolText,fontSize:17,fontWeight:FontWeight.bold)),const SizedBox(height:8),Text('الهدف: '+goal.toString()+' صفحة • المنجز اليوم: '+read.toString(),style:const TextStyle(color:_toolMuted)),const SizedBox(height:8),LinearProgressIndicator(value:(read/goal).clamp(0.0,1.0),color:_toolAccent,backgroundColor:_toolBorder),const SizedBox(height:8),Text('المتبقي اليوم: '+(goal-read).clamp(0,goal).toString()+' صفحة • مدة الختم التقريبية: '+(604/goal).ceil().toString()+' يوماً',style:const TextStyle(color:_toolMuted,fontSize:11)),Wrap(spacing:7,children:[FilledButton.icon(onPressed:()async{setState(()=>read=(read+1).clamp(0,604));await save();},icon:const Icon(Icons.add),label:const Text('سجل صفحة')),OutlinedButton.icon(onPressed:read==0?null:()async{setState(()=>read--);await save();},icon:const Icon(Icons.remove),label:const Text('تراجع')),TextButton(onPressed:()async{final c=TextEditingController(text:goal.toString());final v=await showDialog<int>(context:context,builder:(ctx)=>AlertDialog(title:const Text('الورد اليومي'),content:TextField(controller:c,keyboardType:TextInputType.number),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('إلغاء')),TextButton(onPressed:()=>Navigator.pop(ctx,int.tryParse(c.text)),child:const Text('حفظ'))]));c.dispose();if(v!=null&&v>0&&v<=100){setState(()=>goal=v);await save();}},child:const Text('تعديل الهدف'))]) ])),
 const SizedBox(height:10),_ToolCard(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('العلامات المرجعية • آخر صفحة: '+last.toString(),style:const TextStyle(color:_toolText,fontWeight:FontWeight.bold)),OutlinedButton.icon(onPressed:bookmark,icon:const Icon(Icons.bookmark_add),label:const Text('حفظ آخر صفحة')),if(marks.isEmpty)const Text('لا توجد علامات بعد.',style:TextStyle(color:_toolMuted)),...marks.map((v)=>ListTile(dense:true,title:Text('صفحة '+v.toString(),style:const TextStyle(color:_toolText)),trailing:IconButton(onPressed:()async{setState(()=>marks.remove(v));await save();},icon:const Icon(Icons.delete_outline,color:_toolMuted))))])),
 ]);}
class _Backup extends StatefulWidget{const _Backup();@override State<_Backup> createState()=>_BackupState();}
class _BackupState extends State<_Backup>{
 bool busy=false;static const exact={'reader_font_size','library_favorites','library_last_read','quran_last_page','quran_bookmarks_v1','quran_daily_goal','quran_daily_pages','quran_daily_date','local_reminders_v1','prayer_times_city','prayer_times_method'};
 bool include(String k)=>exact.contains(k)||k.startsWith('reader_scroll_')||k.startsWith('taqibat_completed_')||k.startsWith('night_prayer_')||k.startsWith('tasbeeh_count_')||k.startsWith('quran_');
 Future<void> export()async{setState(()=>busy=true);try{final p=await SharedPreferences.getInstance(),data=<String,dynamic>{};for(final k in p.getKeys().where(include)){final v=p.get(k);if(v is String||v is bool||v is int||v is double||v is List<String>)data[k]=v;}final raw=jsonEncode({'app':'al_kamil','schema':1,'data':data,'created_at':DateTime.now().toIso8601String()});await Clipboard.setData(ClipboardData(text:raw));if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('نُسخت النسخة الاحتياطية إلى الحافظة؛ احفظها في مكان آمن.')));}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تعذّر إنشاء النسخة.')));}finally{if(mounted)setState(()=>busy=false);}}
 Future<void> restore()async{final c=TextEditingController();final raw=await showDialog<String>(context:context,builder:(ctx)=>AlertDialog(title:const Text('استعادة نسخة احتياطية'),content:TextField(controller:c,minLines:4,maxLines:8,decoration:const InputDecoration(hintText:'الصق النسخة هنا')),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('إلغاء')),TextButton(onPressed:()=>Navigator.pop(ctx,c.text),child:const Text('استعادة'))]));c.dispose();if(raw==null||raw.trim().isEmpty)return;setState(()=>busy=true);try{final d=jsonDecode(raw);if(d is! Map||d['app']!='al_kamil'||d['schema']!=1||d['data'] is! Map)throw const FormatException();final data=Map<String,dynamic>.from(d['data']);if(data.length>500||data.keys.any((k)=>!include(k)))throw const FormatException();final validValues=data.values.every((v)=>v is String||v is bool||v is int||v is double||(v is List&&v.every((x)=>x is String)));if(!validValues)throw const FormatException();final p=await SharedPreferences.getInstance();for(final e in data.entries){final v=e.value;if(v is String)await p.setString(e.key,v);else if(v is bool)await p.setBool(e.key,v);else if(v is int)await p.setInt(e.key,v);else if(v is double)await p.setDouble(e.key,v);else if(v is List&&v.every((x)=>x is String))await p.setStringList(e.key,v.cast<String>());else throw const FormatException();}if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('اكتملت استعادة البيانات.')));}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('النسخة غير صالحة؛ لم تكتمل الاستعادة.')));}finally{if(mounted)setState(()=>busy=false);}}
 @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(14),children:[const _ToolCard(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('نسخ بياناتك واستعادتها',style:TextStyle(color:_toolText,fontSize:17,fontWeight:FontWeight.bold)),SizedBox(height:7),Text('نسخ المفضلة ومواضع القراءة والورد والعلامات والتذكيرات والتقدم المحفوظ. لا تُرسل البيانات إلى خادم؛ تُنسخ كنص إلى الحافظة.',style:TextStyle(color:_toolMuted,height:1.7,fontSize:12))])),const SizedBox(height:10),_ToolCard(Column(children:[SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:busy?null:export,icon:const Icon(Icons.copy_all),label:const Text('إنشاء نسخة احتياطية ونسخها'))),OutlinedButton.icon(onPressed:busy?null:restore,icon:const Icon(Icons.restore),label:const Text('استعادة من نص منسوخ')),if(busy)const LinearProgressIndicator()]))]);}

String approximateHijriDate(DateTime date){
 int jd(int y,int m,int d){final a=((14-m)/12).floor(),yy=y+4800-a,mm=m+12*a-3;return d+((153*mm+2)/5).floor()+365*yy+(yy/4).floor()-(yy/100).floor()+(yy/400).floor()-32045;}
 int ijd(int y,int m,int d)=>d+(29.5*(m-1)).ceil()+(y-1)*354+((3+11*y)/30).floor()+1948439;
 final j=jd(date.year,date.month,date.day),y=((30*(j-1948439)+10646)/10631).floor(),m=(((j-ijd(y,1,1))/29.5).floor()+1).clamp(1,12),d=j-ijd(y,m,1)+1;
 const names=['محرّم','صفر','ربيع الأول','ربيع الآخر','جمادى الأولى','جمادى الآخرة','رجب','شعبان','رمضان','شوّال','ذو القعدة','ذو الحجة'];
 return d.toString()+' '+names[m-1]+' '+y.toString()+' هـ (تقريبي)';
}
class HijriDateInfoCard extends StatelessWidget{const HijriDateInfoCard({super.key,required this.date});final DateTime date;@override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:_toolPanel,borderRadius:BorderRadius.circular(16),border:Border.all(color:_toolBorder)),child:Row(children:[const Icon(Icons.calendar_month,color:_toolAccent),const SizedBox(width:9),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('التاريخ الهجري الحسابي',style:TextStyle(color:_toolMuted,fontSize:10)),Text(approximateHijriDate(date),style:const TextStyle(color:_toolText,fontWeight:FontWeight.bold)),const Text('قد يختلف عن التقويم الرسمي بحسب ثبوت الهلال.',style:TextStyle(color:_toolMuted,fontSize:9))]))]));}
